    {
      "id": "faraday-experiment",
      "kind": "content",
      "eyebrow": "历史实验",
      "headline": "法拉第的实验：磁生电",
      "lead": "磁铁与线圈的相对运动能产生电流，静止则无。",
      "notes": "1831 年法拉第发现，当磁铁插入或拔出线圈时，电流计指针偏转，说明产生了电流。磁铁静止时指针回零。这个实验的关键是“变化”——磁通量的变化。可以让学生思考：如果磁铁在线圈中不动，但线圈运动，是否也会产生电流？",
      "blocks": [
        {
          "id": "b_faraday_statement",
          "type": "statement",
          "intent": "陈述法拉第实验的核心现象：磁铁运动产生电流，静止无电流"
        },
        {
          "id": "b_faraday_sim",
          "type": "sim",
          "intent": "交互模拟：拖动磁铁插入或拔出线圈，观察电流表指针偏转方向与大小"
        }
      ]
    },
    {
      "id": "lens-law",
      "kind": "content",
      "eyebrow": "方向判断",
      "headline": "楞次定律：感应电流的方向",
