          "intent": "引用'来拒去留'作为直观记忆"
        }
      ]
    },
    {
      "id": "motional-emf",
      "kind": "content",
      "eyebrow": "动生电动势",
      "headline": "导体棒切割磁感线",
      "lead": "导体棒在磁场中运动时，棒两端产生电动势。",
      "notes": "这是动生电动势的简单模型。当导体棒以速度 $v$ 垂直切割磁感线时，电动势 $E = Blv$。如果回路闭合，就有电流。如果速度方向与磁场平行，则无电动势。强调：即使回路不闭合，电动势依然存在，只是没有电流。",
      "blocks": [
        {
          "id": "b_motional_flow",
          "type": "flow",
          "intent": "展示导体棒在磁场中运动的模型，标注速度、磁场、电动势方向"
        },
        {
          "id": "b_motional_formula",
          "type": "formula",
          "intent": "给出动生电动势公式 E = Blv",
          "latex": "E = Blv"
        }
      ]
    },
    {
      "id": "faraday-law",
      "kind": "content",
      "eyebrow": "定量规律",
      "headline": "法拉第电磁感应定律",
      "lead": "感应电动势与磁通量变化率成正比。",
      "notes": "法拉第电磁感应定律是电磁感应的核心定量规律：$E = -\\frac{d\\Phi}{dt}$。负号来自楞次定律，表示方向。如果磁通量变化率恒定，则电动势恒定。例如，导体棒匀速切割时，磁通量均匀变化，电动势恒定。",
      "blocks": [
        {
          "id": "b_faradaylaw_formula",
          "type": "formula",
          "intent": "给出法拉第电磁感应定律公式 E = -dΦ/dt",
          "latex": "E = -\\frac{d\\Phi}{dt}"
        },
        {
          "id": "b_faradaylaw_callout",
          "type": "callout",
          "intent": "解释负号的意义：表示感应电动势的方向总是阻碍磁通量的变化"
        }
      ]
    },
