      "blocks": [
        {
          "id": "b_motmicro_flow",
          "type": "flow",
          "intent": "展示电子在磁场中受洛伦兹力的示意图，说明电动势的产生"
        },
        {
          "id": "b_motmicro_formula",
          "type": "formula",
          "intent": "推导 E = Blv 从洛伦兹力出发",
          "latex": "E = Blv"
        }
      ]
    },
    {
      "id": "induced-emf",
      "kind": "content",
      "eyebrow": "感生电动势",
      "headline": "感生电动势：变化的磁场产生电场",
      "lead": "即使没有导体，变化的磁场也会在空间激发涡旋电场。",
      "notes": "这是麦克斯韦对法拉第定律的深刻理解：变化的磁场产生涡旋电场，涡旋电场对电荷做功产生电动势。感生电动势与动生电动势本质相同，都是磁通量变化引起，但非静电力不同：动生来自洛伦兹力，感生来自涡旋电场。",
      "blocks": [
        {
          "id": "b_induced_statement",
