        {
          "id": "b_transformer_formula",
          "type": "formula",
          "intent": "给出变压器电压比公式 U1/U2 = n1/n2",
          "latex": "\\frac{U_1}{U_2} = \\frac{n_1}{n_2}"
        }
      ]
